 void verify(String email,String credential)throws Exception{JSONObject body=new JSONObject();if(credential.startsWith("http://")||credential.startsWith("https://")){android.net.Uri link=android.net.Uri.parse(credential);String token=link.getQueryParameter("token");if(token==null)token=link.getQueryParameter("token_hash");if(token==null)throw new IllegalArgumentException("This verification link is incomplete");body.put("token_hash",token).put("type","magiclink");}else body.put("email",email).put("token",credential).put("type","email");JSONObject result=new JSONObject(new String(request("POST","/auth/v1/verify",null,"application/json",body.toString().getBytes(StandardCharsets.UTF_8)),StandardCharsets.UTF_8));access=result.getString("access_token");userId=result.getJSONObject("user").getString("id");}
